42	/// #[pin_data]
43	/// struct Example {
44	///     c: u32,
45	///     #[pin]
46	///     d: SpinLock<Inner>,
47	/// }
48	///
49	/// impl Example {
50	///     fn new() -> impl PinInit<Self> {
51	///         pin_init!(Self {
52	///             c: 10,
53	///             d <- new_spinlock!(Inner { a: 20, b: 30 }),
54	///         })
55	///     }
56	/// }
57	///
58	/// // Allocate a boxed `Example`.
59	/// let e = KBox::pin_init(Example::new(), GFP_KERNEL)?;
60	/// assert_eq!(e.c, 10);
61	/// assert_eq!(e.d.lock().a, 20);
62	/// assert_eq!(e.d.lock().b, 30);
63	/// # Ok::<(), Error>(())
64	/// ```
