143	static inline bool hub_is_port_power_switchable(struct usb_hub *hub)
144	{
145		__le16 hcs;
146	
147		if (!hub)
148			return false;
149		hcs = hub->descriptor->wHubCharacteristics;
150		return (le16_to_cpu(hcs) & HUB_CHAR_LPSM) < HUB_CHAR_NO_LPSM;
151	}
