158	static inline int hub_is_superspeedplus(struct usb_device *hdev)
159	{
160		return (hdev->descriptor.bDeviceProtocol == USB_HUB_PR_SS &&
161			le16_to_cpu(hdev->descriptor.bcdUSB) >= 0x0310 &&
162			hdev->bos && hdev->bos->ssp_cap);
163	}
